// The query executed by SearchNodes.
const SearchNodes_Operation = `
query SearchNodes ($query: String!, $mode: FindNodesMode, $filter: NodeFilter, $sortProperty: NodePropertySort, $limit: Int, $offset: Int, $scope: String, $appRef: ID, $orgId: ID, $withProperties: Boolean!, $withData: Boolean!) {
	findNodes(query: $query, mode: $mode, filter: $filter, sortProperty: $sortProperty, limit: $limit, offset: $offset, scope: $scope, appRef: $appRef, orgId: $orgId) {
		total
		degraded
		reason
		scope {
			kind
			label
			source
			ownerUrn
			memoryUrns
			droppedCount
		}
		hits {
			score
			vector {
				abstractStale
			}
			node {
				id
				memoryId
				loc
				name
				nodeType
				tags
				description
				abstract
				updatedAt
				properties @include(if: $withProperties)
				data @include(if: $withData)
			}
		}
	}
}
`

// Ranked node search backing `hadron search` (#135). Same unified findNodes
// field as nodes.graphql's FindNodes, but a search-shaped selection: per-hit
// score, abstract/description, and the vector abstract-staleness flag — so a
// result list is assessable at a glance without one `node get` per hit. Kept
// separate from FindNodes so the browse/list callers (`node ls`, exports, spec
// reads) don't pay for abstract payloads they never render.
